select '6eaec5d3-4786-55a2-8dc6-a457edd5b16b public mapping' check_name,((select count(*) from jsonb_array_elements(math_private.release_catalog('6815943a-42c1-5eae-b711-449ac403b9fb')) x where x->>'leaf_id'='3ae7907d-32a4-519a-898c-ea65ac73de6b' and x->>'essay_question_id'='6eaec5d3-4786-55a2-8dc6-a457edd5b16b')=1) passed
union all
select '6eaec5d3-4786-55a2-8dc6-a457edd5b16b profile' check_name,((with candidates as(select ep.id,case ep.scope when 'LEAF' then 4 when 'PROBLEM' then 3 when 'EXAM' then 2 else 1 end rank from public.math_subproblems l join public.math_problems pr on pr.id=l.problem_id join public.math_problem_sets ps on ps.id=pr.problem_set_id join public.math_evaluation_profiles ep on ep.state='ACTIVE' and ep.response_format=l.response_format and (ep.leaf_id=l.id or ep.problem_id=l.problem_id or ep.essay_exam_id=ps.essay_exam_id or (ep.scope='COMMON_MATH_RUBRIC' and l.allow_common_rubric)) where l.id='3ae7907d-32a4-519a-898c-ea65ac73de6b' and pr.state='ACTIVE' and ps.state='ACTIVE') select count(*)=1 and bool_and(id='8e58dc31-ac8f-528c-b18f-ddc1a8e8a3ea'::uuid) from candidates where rank=(select max(rank) from candidates))) passed
union all
select '6eaec5d3-4786-55a2-8dc6-a457edd5b16b Worker evidence' check_name,(exists(select 1 from public.math_subproblems l join public.math_problems pr on pr.id=l.problem_id where l.id='3ae7907d-32a4-519a-898c-ea65ac73de6b' and jsonb_array_length(math_private.hanyang_worker_references(jsonb_build_object('leaf',to_jsonb(l),'problem',to_jsonb(pr),'sources',(select jsonb_agg(to_jsonb(s)) from public.math_source_artifacts s where s.problem_id=pr.id)))->'official_images')>0)) passed
